import { PixelImage } from './pixel-art';

/**
 * Cofre trazado píxel por píxel desde la referencia que adjuntó Gaspar.
 * Se guarda como paleta e índices dentro del código: no se carga un PNG externo.
 * El índice cero es transparente; cada otro índice conserva el RGB exacto.
 */
export const CHEST_WIDTH = 36;
export const CHEST_HEIGHT = 45;
const palette =
  '';
const pixels =
  '';

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function decode(base64: string): Uint8Array {
  const bytes = new Uint8Array(Math.floor((base64.length * 3) / 4));
  let bits = 0;
  let pending = 0;
  let count = 0;
  for (const character of base64) {
    if (character === '=') break;
    const digit = BASE64.indexOf(character);
    if (digit < 0) continue;
    pending = (pending << 6) | digit;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes[count++] = (pending >>> bits) & 255;
    }
  }
  return bytes.subarray(0, count);
}
const COLORS = decode(palette);
const INDICES = decode(pixels);

/** La escala entera amplía el ícono sin suavizar ni inventar colores. */
export function drawPixelChest(scale = 1): PixelImage {
  const image = new PixelImage(CHEST_WIDTH * scale, CHEST_HEIGHT * scale);
  for (let y = 0; y < CHEST_HEIGHT; y++)
    for (let x = 0; x < CHEST_WIDTH; x++) {
      const index = INDICES[y * CHEST_WIDTH + x] ?? 0;
      if (index === 0) continue;
      const color = [
        COLORS[index * 3] ?? 0,
        COLORS[index * 3 + 1] ?? 0,
        COLORS[index * 3 + 2] ?? 0,
      ] as const;
      for (let dy = 0; dy < scale; dy++)
        for (let dx = 0; dx < scale; dx++) image.set(x * scale + dx, y * scale + dy, color);
    }
  return image;
}
